def sequence(n):
    if n <= 2:
        return 1

    dp = [0] * (n + 1)
    dp[1] = dp[2] = 1

    for i in range(3, n + 1):
        dp[i] = dp[dp[i-1]] + dp[i - dp[i-1]]

    return dp[n]
